def isL(cs):
    ys=[a for a,b in cs]; xs=[b for a,b in cs]
    h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
    if len(cs)!=h+w-1: return False
    s={(a,b) for a,b in cs}
    for cy,cx in s:
        vseg=all((y,cx) in s for y in range(min(ys),max(ys)+1))
        hseg=all((cy,x) in s for x in range(min(xs),max(xs)+1))
