def Lcorner(cs):
    s=set(cs); ys=[a for a,b in cs]; xs=[b for a,b in cs]
    h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
    if len(cs)!=h+w-1 or h<2 or w<2: return None
    for (cy,cx) in s:
        if all((y,cx) in s for y in range(min(ys),max(ys)+1)) and all((cy,x) in s for x in range(min(xs),max(xs)+1)):
            vd=(1,0) if (cy+1,cx) in s and cy!=max(ys) else (-1,0)
            hd=(0,1) if (cy,cx+1) in s and cx!=max(xs) else (0,-1)
            # arm directions away from corner
            vdir = (1,0) if cy==min(ys) else (-1,0)
            hdir = (0,1) if cx==min(xs) else (0,-1)
            return (cy,cx),vdir,hdir
    return None
